svg.script:
(function () {
  var frame = document.getElementById("game");
  var back = document.getElementById("back");
  var refresh = document.getElementById("refresh");
  var direct = document.getElementById("direct");

  var htmlURL = "./index.html";
  var baseURL = new URL("./", document.baseURI).href;

  function showError(message) {
    frame.srcdoc =
      "<!doctype html><html><body style='" +
      "margin:0;padding:24px;font:14px monospace;" +
      "color:#b00;background:#fff'>" +
      "<pre style='white-space:pre-wrap'>" +
      String(message)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;") +
      "</pre></body></html>";
  }

  function loadGame() {
    frame.srcdoc =
      "<!doctype html><html><body style='" +
      "margin:0;padding:24px;font:14px monospace'>" +
      "Loading game...</body></html>";

    fetch(new URL(htmlURL, document.baseURI).href, {
      credentials: "same-origin"
    })
      .then(function (response) {
        if (!response.ok) {
          throw new Error(
            "HTTP " + response.status +
            " while loading " + htmlURL
          );
        }

        return response.text();
      })
      .then(function (html) {
        var doc = new DOMParser().parseFromString(
          html,
          "text/html"
        );

        var base = doc.createElement("base");
        base.href = baseURL;

        if (doc.head) {
          doc.head.insertBefore(
            base,
            doc.head.firstChild
          );
        } else {
          var head = doc.createElement("head");
          head.appendChild(base);

          doc.documentElement.insertBefore(
            head,
            doc.body || null
          );
        }

        frame.srcdoc =
          "<!doctype html>" +
          doc.documentElement.outerHTML;
      })
      .catch(function (error) {
        showError(error.message || String(error));
      });
  }

  back.addEventListener("click", function () {
    if (history.length > 1) {
      history.back();
    } else {
      location.href = "../../index.html";
    }
  });

  refresh.addEventListener("click", function () {
    loadGame();
  });

  direct.addEventListener("click", function () {
    location.href = "./index.svg";
  });

  loadGame();
})();
